INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5600, 'report', '/rɪˈpɔːrt/', 'noun', '{"zh-TW":["報告；報告書"],"en":["a written or spoken account of a topic or event"]}', NULL, 'annual report / submit a report', '[{"en":"The team submitted the quarterly sales report.","zh-TW":"團隊提交了季度銷售報告。"},{"en":"Her report provided valuable insights for management.","zh-TW":"她的報告為管理層提供了寶貴見解。"}]', '{"verb":"report","noun":"reporter","adjective":"reported"}', NULL, 2, 5600, 201),
(5601, 'report on findings', '/rɪˈpɔːrt ɒn ˈfaɪndɪŋz/', 'verb', '{"zh-TW":["報告調查結果"],"en":["to present conclusions derived from research or investigation"]}', NULL, 'report on audit findings / report on research findings', '[{"en":"The inspector will report on findings to the board next week.","zh-TW":"檢查員將於下週向董事會報告調查結果。"},{"en":"The team was asked to report on findings from the customer survey.","zh-TW":"團隊被要求報告客戶調查的調查結果。"}]', NULL, NULL, 5, 5601, NULL),
(5602, 'report writing', '/rɪˈpɔːrt ˈraɪtɪŋ/', 'noun', '{"zh-TW":["報告撰寫"],"en":["the process of preparing a structured document communicating findings or recommendations"]}', NULL, 'improve report writing / professional report writing', '[{"en":"Clear report writing is essential for effective business communication.","zh-TW":"清晰的報告撰寫對於有效的業務溝通至關重要。"},{"en":"Report writing skills are highly valued in consulting and finance roles.","zh-TW":"報告撰寫技能在諮詢和財務職位中備受重視。"}]', NULL, NULL, 5, 5602, NULL),
(5603, 'reporting line', '/rɪˈpɔːrtɪŋ laɪn/', 'noun', '{"zh-TW":["匯報關係；匯報線"],"en":["the chain of authority defining who reports to whom in an organization"]}', NULL, 'clear reporting line / change the reporting line / reporting line structure', '[{"en":"His reporting line was changed after the reorganization.","zh-TW":"他的匯報關係在重組後發生了變化。"},{"en":"A clear reporting line prevents confusion about authority.","zh-TW":"清晰的匯報關係防止了對授權的混淆。"}]', NULL, NULL, 5, 5603, NULL),
(5604, 'repossession', '/''riːpəˌzeʃən/', 'noun', '{"zh-TW":["收回；沒收；取回"],"en":["the action of a creditor reclaiming possession of property when the owner defaults on payments"]}', NULL, 'face repossession / avoid repossession / repossession order', '[{"en":"The bank initiated repossession proceedings after twelve months of missed mortgage payments.","zh-TW":"銀行在十二個月的未付按揭款項後啟動了收回房產程序。"},{"en":"Seeking financial advice early can help homeowners avoid repossession.","zh-TW":"及早尋求財務建議可以幫助房主避免房產被收回。"}]', '{"verb":"repossess"}', NULL, 4, 5604, NULL),
(5605, 'represent', '/ˌrɛprɪˈzɛnt/', 'verb', '{"zh-TW":["代表；象徵"],"en":["to act or speak for someone; to symbolize"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"present","meaning":"present (呈現)"}}', 'represent the company / represent a change', '[{"en":"She represents the company at trade shows.","zh-TW":"她代表公司參加商展。"},{"en":"This represents a significant change in policy.","zh-TW":"這代表政策的重大改變。"}]', '{"noun":"representation, representative","adjective":"representative"}', NULL, 3, 5605, NULL),
(5606, 'representation', '/ˌreprɪzenˈteɪʃən/', 'noun', '{"zh-TW":["代表；陳述"],"en":["the action of speaking on behalf of someone; also a formal statement"]}', NULL, 'legal representation / seek representation / union representation', '[{"en":"All employees have the right to union representation.","zh-TW":"所有員工都有工會代表的權利。"},{"en":"She provided written representations to the regulatory committee.","zh-TW":"她向監管委員會提交了書面陳述。"}]', '{"verb":"represent","noun":"representative"}', NULL, 5, 5606, 616),
(5607, 'representative', 'ˌrɛprɪˈzɛntətɪv', 'noun', '{"zh-TW":["代表；代理人","業務員"],"en":["a person acting on behalf of another","a sales agent"]}', NULL, 'sales representative/customer representative', '[{"en":"Our sales representative will contact you.","zh-TW":"我們的銷售代表將與您聯繫。"}]', '{"verb":"represent","adjective":"representative","adverb":"representatively"}', NULL, 5, 5607, 440),
(5608, 'representative sample', '/ˌreprɪˈzentətɪv ˈsɑːmpəl/', 'noun', '{"zh-TW":["代表性樣本"],"en":["a sample reflecting the characteristics of the whole population"]}', NULL, 'draw a representative sample / ensure representative sample / large representative sample', '[{"en":"A representative sample is essential for results that can be generalized.","zh-TW":"代表性樣本對於可以推廣的結果至關重要。"},{"en":"The poll used a representative sample of five thousand voters.","zh-TW":"民調使用了五千名選民的代表性樣本。"}]', NULL, NULL, 5, 5608, NULL),
(5609, 'repudiate', '/rɪˈpjuːdieɪt/', 'verb', '{"zh-TW":["拒絕履行；否認；否定"],"en":["to refuse to accept or be associated with something; to refuse to fulfill an obligation"]}', NULL, 'repudiate a debt / repudiate a claim / repudiate a treaty', '[{"en":"The government repudiated the agreement, claiming it had been signed under duress.","zh-TW":"政府否認了該協議，聲稱它是在脅迫下簽署的。"},{"en":"The auditor repudiated the manipulated financial statements submitted by management.","zh-TW":"審計師否認了管理層提交的被操縱的財務報表。"}]', '{"noun":"repudiation","adjective":"repudiated"}', NULL, 3, 5609, NULL),
(5610, 'repurchase', '/riːˈpɜːrtʃəs/', 'verb', '{"zh-TW":["回購；買回"],"en":["to buy back something previously sold"]}', NULL, 'repurchase shares / repurchase agreement', '[{"en":"The company announced a plan to repurchase 10% of its shares.","zh-TW":"公司宣佈計劃回購10%的股份。"},{"en":"The repurchase agreement was settled within three days.","zh-TW":"回購協議在三天內結算。"}]', '{"noun":"repurchase","adjective":"repurchased"}', NULL, 4, 5610, NULL),
(5611, 'repurchase agreement', '/rɪˈpɜːrtʃɪs əˈɡriːmənt/', 'noun', '{"zh-TW":["回購協議"],"en":["a short-term borrowing arrangement where securities are sold and then repurchased"]}', NULL, 'enter a repurchase agreement / repurchase agreement rate', '[{"en":"The central bank uses repurchase agreements to manage short-term liquidity.","zh-TW":"中央銀行使用回購協議管理短期流動性。"},{"en":"Repurchase agreements are commonly used in money market operations.","zh-TW":"回購協議在貨幣市場操作中被廣泛使用。"}]', '{"abbreviation":"repo"}', NULL, 5, 5611, NULL),
(5612, 'reputation', '/ˌrɛpjuˈteɪʃən/', 'noun', '{"zh-TW":["聲譽；名譽"],"en":["the opinion people have about someone"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"put","meaning":"think (思考)"},"suffix":{"text":"-ation","meaning":"狀態"}}', 'good reputation / damage one''s reputation / build a reputation', '[{"en":"The company has an excellent reputation.","zh-TW":"公司享有卓越聲譽。"},{"en":"One mistake can damage your reputation.","zh-TW":"一個錯誤可以損害你的聲譽。"}]', '{"adjective":"reputable"}', NULL, 4, 5612, NULL),
(5613, 'reputation management', '/ˌrepjʊˈteɪʃən ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["聲譽管理"],"en":["protecting and improving a company''s public image"]}', NULL, 'online reputation management / crisis reputation management', '[{"en":"Reputation management became a priority after the incident.","zh-TW":"事件發生後，聲譽管理成為首要任務。"},{"en":"Social media has made reputation management more challenging.","zh-TW":"社群媒體使聲譽管理更具挑戰性。"}]', '{"verb":"manage reputation","adjective":"reputable"}', NULL, 5, 5613, NULL),
(5614, 'reputational risk', '/ˌrepjʊˈteɪʃənl rɪsk/', 'noun', '{"zh-TW":["聲譽風險"],"en":["the risk that negative perceptions will damage a company''s reputation"]}', NULL, 'manage reputational risk / reputational risk assessment', '[{"en":"A data breach creates significant reputational risk for the company.","zh-TW":"數據洩露對公司造成了重大聲譽風險。"},{"en":"Proactive crisis communication mitigates reputational risk.","zh-TW":"積極的危機溝通降低了聲譽風險。"}]', NULL, NULL, 5, 5614, NULL),
(5615, 'request', '/rɪˈkwɛst/', 'noun', '{"zh-TW":["請求；要求"],"en":["an act of asking for something"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"quest","meaning":"seek (尋求)"}}', 'make a request / upon request / request for information', '[{"en":"We received a request for additional funding.","zh-TW":"我們收到了追加資金的請求。"},{"en":"Samples are available upon request.","zh-TW":"樣品可依要求提供。"}]', '{"verb":"request"}', NULL, 3, 5615, 202),
(5616, 'request for proposal', '/rɪˈkwest fɔːr prəˈpoʊzəl/', 'noun', '{"zh-TW":["提案邀請書；招標書"],"en":["a document inviting suppliers to submit proposals for a project"]}', NULL, 'issue a request for proposal / respond to a request for proposal', '[{"en":"The company issued a request for proposal for its new IT system.","zh-TW":"公司為其新IT系統發出了提案邀請書。"},{"en":"Suppliers had two weeks to respond to the request for proposal.","zh-TW":"供應商有兩週時間回應提案邀請書。"}]', '{"abbreviation":"RFP"}', NULL, 5, 5616, NULL),
(5617, 'request for quotation', '/rɪˈkwest fɔːr kwoʊˈteɪʃən/', 'noun', '{"zh-TW":["詢價書；報價請求"],"en":["a document sent to suppliers requesting a price for goods or services"]}', NULL, 'send a request for quotation / respond to a request for quotation', '[{"en":"The purchasing team sent a request for quotation to five vendors.","zh-TW":"採購團隊向五家供應商發送了詢價書。"},{"en":"Reviewing multiple quotations ensures competitive pricing.","zh-TW":"審查多份報價確保了有競爭力的定價。"}]', '{"abbreviation":"RFQ"}', NULL, 5, 5617, NULL),
(5618, 'require', '/rɪˈkwaɪər/', 'verb', '{"zh-TW":["需要；要求"],"en":["to need; to demand by rule"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"quire","meaning":"seek (尋求)"}}', 'require approval / required by law / as required', '[{"en":"This position requires five years of experience.","zh-TW":"此職位需要五年經驗。"},{"en":"All visitors are required to sign in.","zh-TW":"所有訪客必須登記。"}]', '{"noun":"requirement","adjective":"required"}', NULL, 3, 5618, 55),
(5619, 'required', 'rɪˈkwaɪərd', 'adjective', '{"zh-TW":["必要的；規定的","必須的"],"en":["needed or demanded","obligatory"]}', NULL, 'required documents/required skills', '[{"en":"Please submit all required documents.","zh-TW":"請提交所有必要文件。"}]', '{"verb":"require","noun":"requirement"}', NULL, 3, 5619, NULL),
(5620, 'required rate of return', '/rɪˈkwaɪərd reɪt əv rɪˈtɜːrn/', 'noun', '{"zh-TW":["要求回報率"],"en":["the minimum return an investor expects before committing capital"]}', NULL, 'set a required rate of return / exceed the required rate of return', '[{"en":"The project was approved as its IRR exceeded the required rate of return.","zh-TW":"該項目獲得批准，因為其IRR超過了要求回報率。"},{"en":"The required rate of return reflects both risk and opportunity cost.","zh-TW":"要求回報率反映了風險和機會成本。"}]', NULL, NULL, 5, 5620, NULL),
(5621, 'requirement', 'rɪˈkwaɪərmənt', 'noun', '{"zh-TW":["要求；需求","條件"],"en":["something that is needed","a necessary condition"]}', NULL, 'meet requirements/list requirements', '[{"en":"Please review the project requirements.","zh-TW":"請查看專案要求。"}]', '{"verb":"require","adjective":"required"}', NULL, 4, 5621, 441),
(5622, 'reschedule', '/ˌriːˈʃedjuːl/', 'verb', '{"zh-TW":["重新安排時間；改期"],"en":["to arrange a new time for a meeting, event, or task"]}', NULL, 'reschedule a meeting / reschedule a delivery', '[{"en":"The client asked to reschedule the meeting to the following week.","zh-TW":"客戶要求將會議改期到下週。"},{"en":"We had to reschedule the product launch due to supply delays.","zh-TW":"由於供應延遲，我們不得不重新安排產品發布時間。"}]', '{"noun":"rescheduling"}', NULL, 4, 5622, NULL),
(5623, 'research', '/rɪˈsɜːrtʃ/', 'noun', '{"zh-TW":["研究；調查"],"en":["careful study of a subject"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"search","meaning":"search (搜索)"}}', 'conduct research / research and development / market research', '[{"en":"The company invests heavily in R&D.","zh-TW":"公司大量投資研發。"},{"en":"Further research is needed.","zh-TW":"需要進一步研究。"}]', '{"verb":"research","noun":"researcher"}', NULL, 3, 5623, 203),
(5624, 'research and development', '/rɪˈsɜːrtʃ ənd dɪˈveləpmənt/', 'noun', '{"zh-TW":["研究與開發"],"en":["activities undertaken to develop new products or improve existing ones"]}', NULL, 'invest in research and development / research and development budget', '[{"en":"The company allocated 10% of revenue to research and development.","zh-TW":"公司將10%的收入分配給研究與開發。"},{"en":"Strong research and development activity drives long-term innovation.","zh-TW":"強大的研究與開發活動推動了長期創新。"}]', '{"abbreviation":"R&D"}', NULL, 5, 5624, NULL),
(5625, 'research methodology', '/''rɪˌsɜːrtʃ meθəˌdɒlədʒi/', 'noun', '{"zh-TW":["研究方法論；研究方法"],"en":["the process used to collect data and information, including the theoretical framework"]}', NULL, 'explain research methodology / choose a research methodology / qualitative research methodology', '[{"en":"Her research methodology combined interviews with statistical analysis.","zh-TW":"她的研究方法論將訪談與統計分析相結合。"},{"en":"Selecting the right research methodology is critical for achieving valid results.","zh-TW":"選擇正確的研究方法論對於獲得有效結果至關重要。"}]', NULL, NULL, 5, 5625, NULL),
(5626, 'research paper', '/rɪˈsɜːrtʃ ˈpeɪpər/', 'noun', '{"zh-TW":["研究論文"],"en":["a written document presenting research findings"]}', NULL, 'write a research paper / publish a research paper', '[{"en":"She published a research paper in an international journal.","zh-TW":"她在國際期刊上發表了一篇研究論文。"},{"en":"The research paper must follow the APA citation format.","zh-TW":"研究論文必須遵循APA引用格式。"}]', NULL, NULL, 5, 5626, NULL),
(5627, 'reseller', '/riːˈselər/', 'noun', '{"zh-TW":["轉售商；經銷商"],"en":["a business that purchases products to resell them, often adding value"]}', NULL, 'authorized reseller / reseller agreement / reseller program', '[{"en":"The software company works with 300 authorized resellers worldwide.","zh-TW":"軟體公司在全球與300家授權經銷商合作。"},{"en":"Resellers often provide localized support and customization.","zh-TW":"轉售商通常提供本地化支援和客製化服務。"}]', '{"verb":"resell","plural":"resellers"}', NULL, 3, 5627, NULL),
(5628, 'reservation', '/ˌrɛzərˈveɪʃən/', 'noun', '{"zh-TW":["預訂","保留意見"],"en":["a booking","doubt or uncertainty"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"serv","meaning":"keep (保持)"},"suffix":{"text":"-ation","meaning":"行為"}}', 'make a reservation / have reservations about / without reservation', '[{"en":"I''d like to make a reservation for two.","zh-TW":"我想預訂兩人座。"},{"en":"I have some reservations about the plan.","zh-TW":"我對計劃有些保留意見。"}]', '{"verb":"reserve"}', NULL, 4, 5628, 56),
(5629, 'reserve', '/rɪˈzɜːrv/', 'verb', '{"zh-TW":["預訂；保留"],"en":["to book; to keep for later use"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"serve","meaning":"keep (保持)"}}', 'reserve a room / cash reserves / reserve the right', '[{"en":"Please reserve a conference room.","zh-TW":"請預訂一間會議室。"},{"en":"We reserve the right to cancel.","zh-TW":"我們保留取消的權利。"}]', '{"noun":"reserve, reservation","adjective":"reserved"}', NULL, 3, 5629, 204),
(5630, 'reserve ratio', '/rɪˈzɜːrv ˈreɪʃioʊ/', 'noun', '{"zh-TW":["準備金比率"],"en":["the fraction of deposits a bank must hold in reserve and not lend out"]}', NULL, 'maintain reserve ratio / increase the reserve ratio', '[{"en":"The central bank raised the reserve ratio to reduce money supply.","zh-TW":"中央銀行提高了準備金比率以減少貨幣供給。"},{"en":"A lower reserve ratio allows banks to lend more and stimulate growth.","zh-TW":"較低的準備金比率允許銀行多放貸並刺激增長。"}]', NULL, NULL, 5, 5630, NULL),
(5631, 'reserve requirement', '/rɪˈzɜːrv rɪˈkwaɪərmənt/', 'noun', '{"zh-TW":["儲備金要求；準備金規定"],"en":["the minimum cash reserves a bank must hold as required by regulations"]}', NULL, 'comply with reserve requirements / reduce reserve requirements', '[{"en":"Banks adjust lending based on the central bank''s reserve requirements.","zh-TW":"銀行根據中央銀行的準備金規定調整貸款。"},{"en":"Reserve requirements act as a buffer against bank runs.","zh-TW":"準備金規定作為應對銀行擠兌的緩衝。"}]', NULL, NULL, 5, 5631, NULL),
(5632, 'reserves', '/rɪˈzɜːrvz/', 'noun', '{"zh-TW":["儲備金；準備金"],"en":["retained earnings or funds set aside for future needs or contingencies"]}', NULL, 'build up reserves / draw on reserves', '[{"en":"The company built up reserves to fund future expansion.","zh-TW":"公司積累了儲備金以資助未來的擴張。"},{"en":"Reserves provide a buffer against unexpected losses or economic downturns.","zh-TW":"儲備金在意外損失或經濟下滑時提供了緩衝。"}]', NULL, NULL, 3, 5632, NULL),
(5633, 'reside', '/rɪˈzaɪd/', 'verb', '{"zh-TW":["居住"],"en":["to live in a place"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"side","meaning":"sit (坐)"}}', 'reside in / place of residence', '[{"en":"She resides in Tokyo.","zh-TW":"她居住在東京。"},{"en":"Please provide your place of residence.","zh-TW":"請提供您的居住地。"}]', '{"noun":"residence, resident, residency","adjective":"residential"}', NULL, 2, 5633, NULL),
(5634, 'residential district', '/''rezɪdenʃəl ˌdɪstrɪkt/', 'noun', '{"zh-TW":["住宅區；住宅地段"],"en":["an area of a town or city designed primarily for housing"]}', NULL, 'live in a residential district / quiet residential district / upscale residential district', '[{"en":"The school is located in a quiet residential district close to public transportation.","zh-TW":"學校位於靠近公共交通的安靜住宅區。"},{"en":"New supermarkets opened in the residential district to serve the growing population.","zh-TW":"新的超市在住宅區開業，為不斷增長的人口提供服務。"}]', NULL, NULL, 5, 5634, NULL),
(5635, 'residual', '/rɪˈzɪdjuəl/', 'adjective', '{"zh-TW":["剩餘的；殘差的"],"en":["remaining after the greater part has been used or removed"]}', NULL, 'residual value / residual income / residual risk', '[{"en":"The residual value of the leased vehicle was set at 30%.","zh-TW":"租賃車輛的剩餘價值設定為30%。"},{"en":"Residual risk remains even after all mitigation measures are applied.","zh-TW":"即使採取了所有緩解措施後，殘餘風險仍然存在。"}]', '{"noun":"residual","adverb":"residually"}', NULL, 3, 5635, 925),
(5636, 'residual value', '/rɪˈzɪdjʊəl ˈvæljuː/', 'noun', '{"zh-TW":["殘值；剩餘價值"],"en":["the estimated value of an asset at the end of its useful life"]}', NULL, 'estimate residual value / factor in residual value', '[{"en":"The residual value of leased vehicles was estimated at 30%.","zh-TW":"租賃車輛的殘值估計為30%。"},{"en":"A higher residual value reduces depreciation charges.","zh-TW":"較高的殘值降低了折舊費用。"}]', NULL, NULL, 5, 5636, NULL),
(5637, 'resign', '/rɪˈzaɪn/', 'verb', '{"zh-TW":["辭職"],"en":["to voluntarily leave a job"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"sign","meaning":"sign (簽署)"}}', 'resign from / letter of resignation / resign as', '[{"en":"He resigned from his position as CEO.","zh-TW":"他辭去了執行長一職。"},{"en":"Please submit your resignation in writing.","zh-TW":"請以書面形式提交辭呈。"}]', '{"noun":"resignation"}', NULL, 2, 5637, 205),
(5638, 'resignation', '/ˌrezɪɡˈneɪʃən/', 'noun', '{"zh-TW":["辭職；辭呈"],"en":["the act of voluntarily leaving a job"]}', NULL, 'submit a resignation / letter of resignation / accept a resignation', '[{"en":"She submitted her resignation after accepting a better offer.","zh-TW":"她在接受更好的工作機會後提交了辭呈。"},{"en":"The CEO''s resignation surprised the entire board.","zh-TW":"執行長的辭職讓整個董事會感到驚訝。"}]', '{"verb":"resign","adjective":"resigned"}', NULL, 4, 5638, NULL),
(5639, 'resilience', '/rɪˈzɪliəns/', 'noun', '{"zh-TW":["恢復力；韌性"],"en":["the capacity to recover quickly from difficulties"]}', NULL, 'build resilience / community resilience / resilience against climate change', '[{"en":"Communities with strong social networks show greater resilience after disasters.","zh-TW":"擁有強大社會網絡的社區在災難後表現出更強的恢復力。"},{"en":"Biodiversity contributes to the resilience of ecosystems under stress.","zh-TW":"生物多樣性有助於生態系統在壓力下的恢復力。"}]', '{"adjective":"resilient","adverb":"resiliently"}', NULL, 4, 5639, NULL),
(5640, 'resilience building', '/''rɪˈzɪliəns ˌbɪldɪŋ/', 'noun', '{"zh-TW":["韌性培養；復原力建立"],"en":["the process of developing the ability to recover from difficulties or adapt to change"]}', NULL, 'resilience building program / focus on resilience building / benefit of resilience building', '[{"en":"The organization invested in resilience building programs to help staff cope with pressure.","zh-TW":"組織投資了韌性培養計劃，幫助員工應對壓力。"},{"en":"Resilience building is a key focus of modern leadership development training.","zh-TW":"韌性培養是現代領導力發展培訓的核心重點。"}]', '{"noun":"resilience"}', NULL, 5, 5640, NULL),
(5641, 'resilient', '/''rɪˈzɪliənt/', 'adjective', '{"zh-TW":["有韌性的；適應力強的"],"en":["able to withstand or recover quickly from difficult conditions"]}', NULL, 'resilient economy / resilient team / resilient mindset', '[{"en":"She demonstrated resilient leadership during the company''s financial crisis.","zh-TW":"她在公司財務危機期間展示了有韌性的領導力。"},{"en":"Building resilient supply chains is essential to handle unexpected disruptions.","zh-TW":"建立有韌性的供應鏈對於應對意外中斷至關重要。"}]', '{"noun":"resilience","adverb":"resiliently"}', NULL, 3, 5641, NULL),
(5642, 'resilient ecosystem', '/rɪˈzɪliənt ˈiːkəʊˌsɪstəm/', 'noun', '{"zh-TW":["有韌性的生態系統"],"en":["an ecosystem capable of absorbing disturbance and recovering quickly"]}', NULL, 'build resilient ecosystems / protect resilient ecosystems / resilient ecosystem services', '[{"en":"Diverse plant communities create resilient ecosystems that withstand drought.","zh-TW":"多樣化的植物群落創造了能夠抵抗乾旱的有韌性的生態系統。"},{"en":"Restoring soil biodiversity makes agricultural systems more resilient.","zh-TW":"恢復土壤生物多樣性使農業系統更具韌性。"}]', NULL, NULL, 5, 5642, NULL),
(5643, 'resilient infrastructure', '/rɪˈzɪliənt ˈɪnfrəstrʌktʃər/', 'noun', '{"zh-TW":["韌性基礎設施"],"en":["infrastructure designed to withstand and recover from disruptions"]}', NULL, 'build resilient infrastructure / invest in resilient infrastructure / resilient infrastructure standards', '[{"en":"Resilient infrastructure withstands climate extremes and rapid recovery.","zh-TW":"韌性基礎設施能夠承受極端氣候並快速恢復。"},{"en":"The city''s resilient infrastructure plan includes flood barriers and redundant power grids.","zh-TW":"城市的韌性基礎設施計畫包括防洪屏障和冗餘電網。"}]', NULL, NULL, 5, 5643, NULL),
(5644, 'resist', '/rɪˈzɪst/', 'verb', '{"zh-TW":["抵抗；抵制"],"en":["to oppose or fight against"]}', '{"prefix":{"text":"re-","meaning":"against"},"root":{"text":"sist","meaning":"stand (站立)"}}', 'resist change / resist pressure / hard to resist', '[{"en":"Many employees resist organizational change.","zh-TW":"許多員工抵制組織變革。"},{"en":"The offer was hard to resist.","zh-TW":"這個提議很難拒絕。"}]', '{"noun":"resistance","adjective":"resistant"}', NULL, 2, 5644, NULL),
(5645, 'resistance band', '/''rɪˌzɪstəns bænd/', 'noun', '{"zh-TW":["彈力帶；阻力帶"],"en":["a stretchable band used as an exercise tool to provide resistance for strength training"]}', NULL, 'use a resistance band / resistance band exercise / resistance band workout', '[{"en":"Resistance bands are versatile and effective tools for building strength without weights.","zh-TW":"彈力帶是無需啞鈴就能增強力量的多功能有效工具。"},{"en":"Physical therapists often use resistance bands in rehabilitation exercises.","zh-TW":"物理治療師通常在康復練習中使用彈力帶。"}]', '{"noun":"resistance"}', NULL, 5, 5645, NULL),
(5646, 'resolution', '/ˌrɛzəˈluːʃən/', 'noun', '{"zh-TW":["解決；決議"],"en":["the action of solving a problem or dispute"]}', NULL, 'conflict resolution / quick resolution', '[{"en":"The customer was pleased with the quick resolution of her issue.","zh-TW":"顧客對她的問題得到迅速解決感到滿意。"},{"en":"Resolution of the dispute took three weeks of negotiation.","zh-TW":"爭議的解決花了三週的談判時間。"}]', '{"verb":"resolve","adjective":"resolved"}', NULL, 4, 5646, 442),
(5647, 'resolve', '/rɪˈzɒlv/', 'verb', '{"zh-TW":["解決；決心","解決；決定"],"en":["to find a solution to a problem","to decide firmly","to find a solution; to decide firmly"]}', '{"prefix":{"text":"re-","meaning":"again (再次)"},"root":{"text":"solve","meaning":"loosen (鬆開)"},"logic":"再次鬆開（解開問題），即「解決」。"}', 'resolve a conflict / resolve an issue / resolve to; resolve an issue / resolve a dispute / resolve to do', '[{"en":"We need to resolve this issue quickly.","zh-TW":"我們需要快速解決這個問題。"},{"en":"She resolved to study harder.","zh-TW":"她決心更用功讀書。"},{"en":"We need to resolve this issue immediately.","zh-TW":"我們需要立即解決這問題。"},{"en":"The dispute was resolved through mediation.","zh-TW":"糾紛通過調解解決了。"}]', '{"noun":"resolution","adjective":"resolute"}', NULL, 3, 5647, 57),
(5648, 'resort', '/rɪˈzɔːrt/', 'noun', '{"zh-TW":["度假村","手段"],"en":["a vacation place","a course of action"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"sort","meaning":"go out (出去)"}}', 'as a last resort / resort to / tourist resort', '[{"en":"We should use legal action as a last resort.","zh-TW":"我們應將法律行動作為最後手段。"},{"en":"The conference was held at a beach resort.","zh-TW":"會議在海灘度假村舉行。"}]', '{"verb":"resort"}', NULL, 2, 5648, NULL),
(5649, 'resort fee', '/rɪˈzɔːrt fiː/', 'noun', '{"zh-TW":["度假村服務費"],"en":["an additional fee charged at a resort for amenities"]}', NULL, 'resort fee included / mandatory resort fee', '[{"en":"A daily resort fee covers access to the gym and pool.","zh-TW":"每日度假村服務費包含使用健身房和游泳池的費用。"},{"en":"The resort fee was not disclosed at the time of booking.","zh-TW":"度假村服務費在預訂時未予披露。"}]', NULL, NULL, 4, 5649, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5650, 'resource', '/rɪˈsɔːrs/', 'noun', '{"zh-TW":["資源"],"en":["a supply that can be used"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"source","meaning":"rise (升起)"}}', 'human resources / natural resources / allocate resources', '[{"en":"We need to allocate resources more efficiently.","zh-TW":"我們需要更有效地分配資源。"},{"en":"Human resources handles employee matters.","zh-TW":"人力資源部處理員工事務。"}]', '{"adjective":"resourceful","verb":"resource"}', NULL, 3, 5650, 206),
(5651, 'resource allocation', '/ˈriːsɔːrs ˌæləˈkeɪʃən/', 'noun', '{"zh-TW":["資源分配"],"en":["the process of assigning available resources to tasks or projects"]}', NULL, 'effective resource allocation / resource allocation plan', '[{"en":"Resource allocation was reviewed to align with the new priorities.","zh-TW":"資源分配根據新的優先事項進行了審查。"},{"en":"Poor resource allocation led to delays on three critical projects.","zh-TW":"資源分配不當導致三個關鍵項目延誤。"}]', '{"verb":"allocate resources"}', NULL, 5, 5651, NULL),
(5652, 'resource allocation plan', '/rɪˈsɔːrs ˌæləˈkeɪʃən plæn/', 'noun', '{"zh-TW":["資源分配計劃"],"en":["a plan specifying how resources will be assigned across projects or activities"]}', NULL, 'create a resource allocation plan / review the resource allocation plan', '[{"en":"The resource allocation plan was approved by the steering committee.","zh-TW":"資源分配計劃獲得了指導委員會的批准。"},{"en":"An accurate resource allocation plan prevents bottlenecks.","zh-TW":"準確的資源分配計劃可防止瓶頸。"}]', NULL, NULL, 5, 5652, NULL),
(5653, 'resource planning', '/ˈriːsɔːrs ˈplænɪŋ/', 'noun', '{"zh-TW":["資源規劃"],"en":["identifying and allocating resources needed to complete a project"]}', NULL, 'resource planning process / resource planning tool / effective resource planning', '[{"en":"Resource planning ensured the team had the right skills at each phase.","zh-TW":"資源規劃確保了團隊在每個階段都具備正確的技能。"},{"en":"Poor resource planning caused delays in the critical path.","zh-TW":"糟糕的資源規劃導致了關鍵路徑上的延遲。"}]', NULL, NULL, 5, 5653, NULL),
(5654, 'resource utilization', '/rɪˈsɔːrs ˌjuːtɪlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["資源利用率"],"en":["the extent to which available resources are being productively used"]}', NULL, 'monitor resource utilization / improve resource utilization', '[{"en":"High resource utilization means fewer idle assets and better returns.","zh-TW":"高資源利用率意味著更少的閒置資產和更好的回報。"},{"en":"Resource utilization reports help managers plan workloads efficiently.","zh-TW":"資源利用率報告幫助管理者有效地規劃工作量。"}]', NULL, NULL, 5, 5654, NULL),
(5655, 'respond', '/rɪˈspɒnd/', 'verb', '{"zh-TW":["回應；回覆"],"en":["to reply; to react"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"spond","meaning":"promise (承諾)"}}', 'respond to / respond quickly / respond in writing', '[{"en":"Please respond to the email by Friday.","zh-TW":"請於週五前回覆郵件。"},{"en":"The company responded quickly to the crisis.","zh-TW":"公司迅速回應了危機。"}]', '{"noun":"response, respondent","adjective":"responsive"}', NULL, 3, 5655, NULL),
(5656, 'response', 'rɪˈspɒns', 'noun', '{"zh-TW":["回應；答覆","響應"],"en":["an answer or reaction","something said or done in reply"]}', NULL, 'prompt response/in response to', '[{"en":"Thank you for your prompt response.","zh-TW":"感謝您的及時回應。"}]', '{"verb":"respond","adjective":"responsive","adverb":"responsively"}', NULL, 3, 5656, 58),
(5657, 'response time', '/rɪˈspɒns taɪm/', 'noun', '{"zh-TW":["回應時間"],"en":["the time taken to reply to a request or query"]}', NULL, 'reduce response time / average response time / response time SLA', '[{"en":"The help desk targets a two-hour response time for all tickets.","zh-TW":"服務台的目標是對所有工單在兩小時內回應。"},{"en":"Faster response times significantly improve customer experience.","zh-TW":"更快的回應時間顯著改善了客戶體驗。"}]', NULL, NULL, 5, 5657, NULL),
(5658, 'responsibility', 'rɪˌspɒnsɪˈbɪlɪti', 'noun', '{"zh-TW":["責任；職責","義務"],"en":["a duty to do something","something you are in charge of"]}', NULL, 'take responsibility/social responsibility', '[{"en":"Each team member has clear responsibilities.","zh-TW":"每個團隊成員都有明確的職責。"}]', '{"adjective":"responsible","adverb":"responsibly"}', NULL, 5, 5658, 617),
(5659, 'responsible', 'rɪˈspɒnsɪbəl', 'adjective', '{"zh-TW":["負責任的；可靠的","應負責的"],"en":["having a duty to do something","trustworthy"]}', NULL, 'responsible for/responsible person', '[{"en":"Who is responsible for this project?","zh-TW":"誰負責這個專案？"}]', '{"noun":"responsibility","adverb":"responsibly"}', NULL, 4, 5659, 59),
(5660, 'responsible tourism', '/rɪˈspɒnsɪbəl ˈtʊərɪzəm/', 'noun', '{"zh-TW":["負責任旅遊"],"en":["tourism that minimizes negative environmental and cultural impact"]}', NULL, 'practice responsible tourism / responsible tourism principles', '[{"en":"Responsible tourism benefits local communities and ecosystems.","zh-TW":"負責任旅遊有益於當地社區和生態系統。"},{"en":"Choose eco-certified hotels as part of responsible tourism.","zh-TW":"選擇具有環保認證的飯店作為負責任旅遊的一部分。"}]', NULL, NULL, 5, 5660, NULL),
(5661, 'rest', '/rɛst/', 'noun', '{"zh-TW":["休息；其餘的"],"en":["a period of relaxing","the remaining part"]}', NULL, 'the rest of / get some rest', '[{"en":"I will handle the rest of the tasks.","zh-TW":"我會處理剩下的任務。"},{"en":"Get some rest before the trip.","zh-TW":"出差前好好休息。"}]', '{"noun":"rest","verb":"rest","adjective":"restful","adjective2":"restless"}', NULL, 1, 5661, NULL),
(5662, 'restated financial', '/rɪˈsteɪtɪd faɪˈnænʃəl/', 'adjective', '{"zh-TW":["經重新申報的財務"],"en":["previously published financial results that have been corrected"]}', NULL, 'restated financial results / restated earnings', '[{"en":"The restated financial results showed lower profits than originally reported.","zh-TW":"經重新申報的財務結果顯示利潤低於原始報告。"},{"en":"An error in accounting led to restated financial statements.","zh-TW":"會計錯誤導致了財務報表的重新申報。"}]', '{"verb":"restate","noun":"restatement"}', NULL, 5, 5662, NULL),
(5663, 'resting heart rate', '/''restɪŋ hɑːrt reɪt/', 'noun', '{"zh-TW":["靜息心率"],"en":["the number of times the heart beats per minute while the body is at rest"]}', NULL, 'measure resting heart rate / lower resting heart rate / monitor resting heart rate', '[{"en":"A lower resting heart rate generally indicates better cardiovascular fitness.","zh-TW":"較低的靜息心率通常表示更好的心血管健康。"},{"en":"Regular aerobic exercise is one of the most effective ways to lower your resting heart rate.","zh-TW":"定期有氧運動是降低靜息心率最有效的方法之一。"}]', '{"noun":"heart rate"}', NULL, 5, 5663, NULL),
(5664, 'restitution', '/ˌrestɪˈtjuːʃən/', 'noun', '{"zh-TW":["賠償；歸還"],"en":["the restoration of something lost or stolen; compensation for loss"]}', NULL, 'order restitution / pay restitution / criminal restitution', '[{"en":"The judge ordered the defendant to pay restitution to the victims.","zh-TW":"法官命令被告向受害者支付賠償金。"},{"en":"Restitution aims to restore the victim to their original position.","zh-TW":"賠償旨在將受害者恢復到原來的狀況。"}]', '{"verb":"restore","adjective":"restorative"}', NULL, 4, 5664, NULL),
(5665, 'restoration', '/ˌrestəˈreɪʃn/', 'noun', '{"zh-TW":["修復；恢復"],"en":["the act of returning something to its original condition"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"stor","meaning":"set up (建立)"},"suffix":{"text":"-ation","meaning":"process (過程)"},"logic":"重新建立的過程，即「修復」。"}', 'art restoration / building restoration', '[{"en":"The restoration of the painting took three years.","zh-TW":"這幅畫的修復花了三年。"},{"en":"The old building underwent a complete restoration.","zh-TW":"這棟老建築進行了全面修復。"}]', '{"verb":"restore"}', NULL, 4, 5665, NULL),
(5666, 'restore', '/rɪˈstɔːr/', 'verb', '{"zh-TW":["恢復；修復"],"en":["to bring back to a former condition"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"store","meaning":"build (建造)"}}', 'restore confidence / restore service / restore to', '[{"en":"We aim to restore customer confidence.","zh-TW":"我們旨在恢復客戶信心。"},{"en":"Service has been fully restored.","zh-TW":"服務已完全恢復。"}]', '{"noun":"restoration"}', NULL, 3, 5666, 926),
(5667, 'restrict', '/rɪˈstrɪkt/', 'verb', '{"zh-TW":["限制；約束"],"en":["to put a limit on"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"strict","meaning":"draw tight (拉緊)"}}', 'restrict access / restrict spending / restricted area', '[{"en":"Access is restricted to authorized personnel.","zh-TW":"僅限授權人員進入。"},{"en":"The budget restricts our spending options.","zh-TW":"預算限制了我們的開支選項。"}]', '{"noun":"restriction","adjective":"restrictive, restricted"}', NULL, 3, 5667, NULL),
(5668, 'restructure', '/ˌriːˈstrʌktʃər/', 'verb', '{"zh-TW":["重組；改組"],"en":["to organize differently"]}', NULL, 'restructure debt / corporate restructuring', '[{"en":"The company plans to restructure its divisions.","zh-TW":"公司計畫重組其部門。"},{"en":"Debt restructuring saved the business.","zh-TW":"債務重組拯救了這家企業。"}]', '{"verb":"restructure","noun":"restructuring"}', NULL, 4, 5668, 717),
(5669, 'restructuring', '/riːˈstrʌktʃərɪŋ/', 'noun', '{"zh-TW":["重組；改組"],"en":["reorganizing a company''s structure, operations, or finances"]}', NULL, 'corporate restructuring / debt restructuring', '[{"en":"The restructuring plan will eliminate 500 jobs.","zh-TW":"重組計劃將裁減500個職位。"},{"en":"Debt restructuring gave the firm a fresh start.","zh-TW":"債務重組給公司提供了重新開始的機會。"}]', '{"verb":"restructure","adjective":"restructured"}', NULL, 5, 5669, 618),
(5670, 'restructuring charge', '/riːˈstrʌktʃərɪŋ tʃɑːrdʒ/', 'noun', '{"zh-TW":["重組費用"],"en":["a one-time expense recorded when reorganizing a company"]}', NULL, 'recognize a restructuring charge / one-off restructuring charge', '[{"en":"The company recorded a 50 million restructuring charge for the layoffs.","zh-TW":"公司為裁員記錄了5000萬元的重組費用。"},{"en":"Restructuring charges were excluded from the adjusted profit figures.","zh-TW":"重組費用從調整後的利潤數字中排除了。"}]', NULL, NULL, 5, 5670, NULL),
(5671, 'restructuring plan', '/riːˈstrʌktʃərɪŋ plæn/', 'noun', '{"zh-TW":["重組計劃"],"en":["a documented strategy for reorganizing a company to improve performance"]}', NULL, 'implement a restructuring plan / restructuring plan announcement', '[{"en":"The board approved a three-year restructuring plan to cut costs.","zh-TW":"董事會批准了為期三年的降成本重組計劃。"},{"en":"A successful restructuring plan can restore profitability.","zh-TW":"成功的重組計劃可以恢復盈利能力。"}]', NULL, NULL, 5, 5671, NULL),
(5672, 'result', '/rɪˈzʌlt/', 'noun', '{"zh-TW":["結果"],"en":["an outcome; a consequence"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"sult","meaning":"jump (跳)"}}', 'as a result / achieve results / result in', '[{"en":"As a result of the merger, profits increased.","zh-TW":"合併的結果是利潤增加了。"},{"en":"The campaign resulted in higher sales.","zh-TW":"活動帶來了更高的銷售額。"}]', '{"verb":"result","adjective":"resulting, resultant"}', NULL, 2, 5672, 444),
(5673, 'results-oriented', 'rɪˈzʌlts ˈɔːriɛntɪd', 'adjective', '{"zh-TW":["以結果為導向的；注重成效的","目標明確的"],"en":["focused on achieving outcomes","driven by results"]}', NULL, 'results-oriented culture/results-oriented manager', '[{"en":"We foster a results-oriented culture.","zh-TW":"我們培育以結果為導向的文化。"}]', NULL, NULL, 5, 5673, NULL),
(5674, 'resume', '/rɪˈzjuːm/', 'verb', '{"zh-TW":["恢復；繼續"],"en":["to begin again after a pause"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"sume","meaning":"take (拿)"}}', 'resume work / resume operations / resume negotiations', '[{"en":"Operations will resume on Monday.","zh-TW":"營運將於週一恢復。"},{"en":"Talks are expected to resume next week.","zh-TW":"會談預計下週恢復。"}]', '{"noun":"resumption"}', NULL, 2, 5674, NULL),
(5675, 'retail', '/ˈriːteɪl/', 'noun', '{"zh-TW":["零售"],"en":["the sale of goods to the public in small quantities","the sale of goods to the public"]}', '{"prefix":{"text":"re-","meaning":"again (再次)"},"root":{"text":"tail","meaning":"cut (切割)"},"logic":"再次切割分售，即「零售」。"}', 'retail price / retail store / retail industry', '[{"en":"The retail price is higher than the wholesale price.","zh-TW":"零售價比批發價高。"},{"en":"She has years of experience in retail.","zh-TW":"她有多年零售業經驗。"},{"en":"The retail price is $49.99.","zh-TW":"零售價為49.99美元。"},{"en":"She has 10 years of retail experience.","zh-TW":"她有十年零售經驗。"}]', '{"noun":"retailer","verb":"retail"}', NULL, 2, 5675, 445),
(5676, 'retail price', '/ˈriːteɪl praɪs/', 'noun', '{"zh-TW":["零售價"],"en":["the price at which goods are sold to the public"]}', NULL, 'suggest retail price / retail price comparison', '[{"en":"The manufacturer suggested retail price is 99 dollars.","zh-TW":"製造商建議的零售價為99元。"},{"en":"Online retailers often undercut the recommended retail price.","zh-TW":"線上零售商通常低於建議零售價銷售。"}]', NULL, NULL, 4, 5676, NULL),
(5677, 'retain', '/rɪˈteɪn/', 'verb', '{"zh-TW":["保留；留住","保持；留住"],"en":["to keep; to continue to have","to continue to have; to keep"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"tain","meaning":"hold (持有)"}}', 'retain customers / retain employees / retain the right; retain customers / retain knowledge / retention rate', '[{"en":"The company strives to retain top talent.","zh-TW":"公司努力留住頂尖人才。"},{"en":"We retain the right to modify terms.","zh-TW":"我們保留修改條款的權利。"},{"en":"Customer retention is a key metric.","zh-TW":"客戶留存率是關鍵指標。"},{"en":"How do we retain skilled workers?","zh-TW":"我們如何留住熟練工人？"}]', '{"noun":"retention","adjective":"retentive"}', NULL, 2, 5677, 207),
(5678, 'retained earnings', '/rɪˈteɪnd ˈɜːrnɪŋz/', 'noun', '{"zh-TW":["保留盈餘；留存收益"],"en":["profits kept by the company rather than paid out as dividends"]}', NULL, 'reinvest retained earnings / retained earnings account', '[{"en":"Retained earnings fund future expansion without new debt.","zh-TW":"保留盈餘為未來擴張提供資金，無需新增債務。"},{"en":"The balance sheet showed $30 million in retained earnings.","zh-TW":"資產負債表顯示保留盈餘為3000萬美元。"}]', NULL, NULL, 5, 5678, NULL),
(5679, 'retention', 'rɪˈtɛnʃən', 'noun', '{"zh-TW":["留住；保留","記憶"],"en":["keeping employees or customers","the ability to retain"]}', NULL, 'employee retention/customer retention', '[{"en":"Improving retention is a top priority.","zh-TW":"提高留存率是首要任務。"}]', '{"verb":"retain","adjective":"retained"}', NULL, 3, 5679, 446),
(5680, 'retention rate', '/rɪˈtenʃən reɪt/', 'noun', '{"zh-TW":["留存率；客戶保留率"],"en":["the percentage of customers or employees retained over a period"]}', NULL, 'improve retention rate / customer retention rate / employee retention rate', '[{"en":"Improving the user interface increased retention rate by 15%.","zh-TW":"改善用戶介面使留存率提高了15%。"},{"en":"High employee retention rates reflect strong company culture.","zh-TW":"高員工留存率反映了強大的公司文化。"}]', '{"verb":"retain"}', NULL, 5, 5680, NULL),
(5681, 'retention strategy', '/rɪˈtenʃən ˈstrætɪdʒi/', 'noun', '{"zh-TW":["留存策略；保留策略"],"en":["a plan designed to keep customers or employees engaged and loyal"]}', NULL, 'develop a retention strategy / customer retention strategy', '[{"en":"A loyalty program is a key part of the customer retention strategy.","zh-TW":"忠誠度計劃是客戶留存策略的重要組成部分。"},{"en":"The retention strategy reduced employee turnover by 20%.","zh-TW":"留存策略將員工離職率降低了20%。"}]', NULL, NULL, 5, 5681, NULL),
(5682, 'reticent', '/''retɪsənt/', 'adjective', '{"zh-TW":["沉默寡言的；不願表達的"],"en":["not revealing one''s thoughts or feelings readily; reserved"]}', NULL, 'reticent personality / remain reticent / reticent about sharing', '[{"en":"He was reticent about his personal life and rarely discussed it at work.","zh-TW":"他對個人生活保持沉默，在工作中很少談及。"},{"en":"She was normally outgoing but became reticent whenever the topic turned to her past.","zh-TW":"她通常很外向，但話題一轉到她的過去時就變得沉默寡言。"}]', '{"adverb":"reticently","noun":"reticence"}', NULL, 3, 5682, NULL),
(5683, 'retire', '/rɪˈtaɪər/', 'verb', '{"zh-TW":["退休"],"en":["to stop working due to age"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"tire","meaning":"draw (拉)"}}', 'retire from / retirement age / retire early', '[{"en":"She plans to retire at 60.","zh-TW":"她計劃60歲退休。"},{"en":"He retired from the company after 30 years.","zh-TW":"他在公司工作30年後退休。"}]', '{"noun":"retirement, retiree","adjective":"retired"}', NULL, 2, 5683, NULL),
(5684, 'retreat', '/''rɪˈtriːt/', 'noun', '{"zh-TW":["靜修所；避靜；退修處"],"en":["a quiet or secluded place for rest or seclusion; a period spent in this way"]}', NULL, 'yoga retreat / meditation retreat / weekend retreat', '[{"en":"The wellness retreat offered yoga, meditation, and organic meals.","zh-TW":"這個健康靜修所提供瑜伽、冥想和有機餐食。"},{"en":"She attended a writing retreat in the mountains to complete her novel.","zh-TW":"她參加了山區的寫作退修活動，以完成她的小說。"}]', NULL, NULL, 3, 5684, NULL),
(5685, 'retrenchment', '/rɪˈtrentʃmənt/', 'noun', '{"zh-TW":["緊縮；削減；裁員"],"en":["the cutting of expenditure; a reduction in the size of a workforce"]}', NULL, 'economic retrenchment / corporate retrenchment / period of retrenchment', '[{"en":"Corporate retrenchment reduced operating costs but lowered employee morale.","zh-TW":"企業緊縮降低了運營成本，但降低了員工士氣。"},{"en":"The government''s fiscal retrenchment included cuts to public services and welfare programs.","zh-TW":"政府的財政緊縮包括削減公共服務和福利計畫。"}]', '{"verb":"retrench","adjective":"retrenched"}', NULL, 4, 5685, NULL),
(5686, 'retrieve', '/rɪˈtriːv/', 'verb', '{"zh-TW":["取回；檢索","取回"],"en":["to get back; to find and bring back","to get something back"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"trieve","meaning":"find (找到)"}}', 'retrieve data / retrieve information / retrieve from; retrieve data / retrieve information / information retrieval', '[{"en":"We can retrieve the deleted files.","zh-TW":"我們可以檢索已刪除的文件。"},{"en":"The system retrieves data automatically.","zh-TW":"系統自動檢索數據。"},{"en":"The system can retrieve archived records.","zh-TW":"系統可以檢索存檔記錄。"},{"en":"Click here to retrieve your password.","zh-TW":"點擊此處找回密碼。"}]', '{"noun":"retrieval"}', NULL, 3, 5686, NULL),
(5687, 'retrospective', '/ˌretrəˈspektɪv/', 'noun', '{"zh-TW":["回顧會議；回顧"],"en":["a meeting where a team reflects on past work to improve future performance"]}', NULL, 'run a retrospective / sprint retrospective / agile retrospective', '[{"en":"The retrospective highlighted that daily standups improved team sync.","zh-TW":"回顧會議強調每日站立會議改善了團隊同步。"},{"en":"Retrospectives are a core ceremony in agile development.","zh-TW":"回顧是敏捷開發的核心儀式。"}]', '{"adjective":"retrospective"}', NULL, 5, 5687, NULL),
(5688, 'return', '/rɪˈtɜːrn/', 'verb', '{"zh-TW":["返回；歸還","回報"],"en":["to come or go back","to give back","profit"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"turn","meaning":"turn (轉)"}}', 'return on investment / return a call / return policy', '[{"en":"The return on investment exceeded expectations.","zh-TW":"投資回報超出預期。"},{"en":"Please return the signed contract.","zh-TW":"請歸還已簽署的合約。"}]', '{"noun":"return"}', NULL, 2, 5688, NULL),
(5689, 'return merchandise authorization', '/rɪˈtɜːrn ˈmɜːrtʃəndaɪz ˌɔːθərɪˈzeɪʃən/', 'noun', '{"zh-TW":["退貨授權"],"en":["an approval for a customer to return a product for a refund or replacement"]}', NULL, 'issue a return merchandise authorization / return merchandise authorization number', '[{"en":"Customers need a return merchandise authorization number to send items back.","zh-TW":"客戶需要退貨授權號碼才能退回商品。"},{"en":"The return merchandise authorization was processed within 24 hours.","zh-TW":"退貨授權在24小時內完成了處理。"}]', '{"abbreviation":"RMA"}', NULL, 5, 5689, NULL),
(5690, 'return on assets', '/rɪˈtɜːrn ɒn ˈæsets/', 'noun', '{"zh-TW":["資產回報率"],"en":["net income divided by total assets, measuring how efficiently assets generate profit"]}', NULL, 'calculate return on assets / improve return on assets', '[{"en":"The company increased its return on assets by 3% through operational improvements.","zh-TW":"公司通過運營改善將資產回報率提高了3%。"},{"en":"Return on assets is used to compare companies within the same industry.","zh-TW":"資產回報率用於比較同一行業內的公司。"}]', '{"abbreviation":"ROA"}', NULL, 5, 5690, NULL),
(5691, 'return on capital employed', '/rɪˈtɜːrn ɒn ˈkæpɪtl ɪmˈplɔɪd/', 'noun', '{"zh-TW":["已動用資本回報率"],"en":["profit before interest and tax as a percentage of capital employed"]}', NULL, 'calculate return on capital employed / improve ROCE', '[{"en":"Return on capital employed of 15% exceeded the cost of capital.","zh-TW":"已動用資本回報率15%超過了資本成本。"},{"en":"ROCE is an important metric for capital-intensive industries.","zh-TW":"已動用資本回報率是資本密集型行業的重要指標。"}]', '{"abbreviation":"ROCE"}', NULL, 5, 5691, NULL),
(5692, 'return on equity', '/rɪˈtɜːrn ɒn ˈekwɪti/', 'noun', '{"zh-TW":["股東權益報酬率"],"en":["net profit expressed as a percentage of shareholders'' equity"]}', NULL, 'strong return on equity / improve return on equity', '[{"en":"A return on equity above 15% is considered excellent.","zh-TW":"股東權益報酬率超過15%被認為非常出色。"},{"en":"The bank reported a return on equity of 12% last year.","zh-TW":"銀行去年報告的股東權益報酬率為12%。"}]', '{"abbreviation":"ROE"}', NULL, 5, 5692, NULL),
(5693, 'return on invested capital', '/rɪˈtɜːrn ɒn ɪnˈvestɪd ˈkæpɪtəl/', 'noun', '{"zh-TW":["投入資本回報率"],"en":["a measure of how efficiently a company uses capital to generate profit"]}', NULL, 'improve return on invested capital / target return on invested capital / analyze return on invested capital', '[{"en":"A high return on invested capital indicates efficient capital allocation.","zh-TW":"高投入資本回報率表明資本配置效率高。"},{"en":"The CFO set a fifteen percent return on invested capital target for the group.","zh-TW":"財務長為集團設定了百分之十五的投入資本回報率目標。"}]', NULL, NULL, 5, 5693, NULL),
(5694, 'return on investment', '/rɪˈtɜːrn ɒn ɪnˈvestmənt/', 'noun', '{"zh-TW":["投資報酬率"],"en":["a measure of profitability relative to the cost of an investment"]}', NULL, 'high return on investment / calculate return on investment', '[{"en":"The project delivered a return on investment of 25%.","zh-TW":"該項目帶來了25%的投資報酬率。"},{"en":"Marketing campaigns are measured by their return on investment.","zh-TW":"行銷活動通過其投資報酬率來衡量。"}]', '{"abbreviation":"ROI"}', NULL, 5, 5694, NULL),
(5695, 'return policy', '/rɪˈtɜːrn ˈpɒlɪsi/', 'noun', '{"zh-TW":["退貨政策"],"en":["the rules under which a product can be returned"]}', NULL, 'flexible return policy / 30-day return policy', '[{"en":"The store offers a 30-day no-questions-asked return policy.","zh-TW":"商店提供30天無條件退貨政策。"},{"en":"Read the return policy before purchasing high-value items.","zh-TW":"購買高價商品前請閱讀退貨政策。"}]', NULL, NULL, 5, 5695, NULL),
(5696, 'return ticket', '/rɪˈtɜːrn ˈtɪkɪt/', 'noun', '{"zh-TW":["來回票"],"en":["a ticket valid for travel to a destination and back"]}', NULL, 'book a return ticket / return ticket price', '[{"en":"A return ticket is usually cheaper than two single tickets.","zh-TW":"來回票通常比兩張單程票便宜。"},{"en":"She bought a return ticket to visit her family.","zh-TW":"她買了一張來回票拜訪家人。"}]', NULL, NULL, 5, 5696, NULL),
(5697, 'returns management', '/rɪˈtɜːrnz ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["退貨管理"],"en":["the process of handling returned products from customers"]}', NULL, 'returns management process / improve returns management', '[{"en":"A simple returns management policy increases customer confidence.","zh-TW":"簡單的退貨管理政策增加了客戶信心。"},{"en":"Reverse logistics focuses on returns management and recycling.","zh-TW":"逆向物流專注於退貨管理和回收利用。"}]', NULL, NULL, 5, 5697, NULL),
(5698, 'reveal', '/rɪˈviːl/', 'verb', '{"zh-TW":["揭露；顯示","揭示；透露"],"en":["to make known something previously hidden","to make known; to show"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"veal","meaning":"veil/cover (遮蓋)"},"logic":"把遮蓋拉回，即「揭露」。"}', 'reveal the truth / reveal information / reveal a secret; reveal information / reveal the truth / reveal findings', '[{"en":"The investigation revealed new evidence.","zh-TW":"調查揭露了新證據。"},{"en":"She revealed her plans for the future.","zh-TW":"她透露了未來的計畫。"},{"en":"The audit revealed several discrepancies.","zh-TW":"審計揭示了幾處差異。"},{"en":"The survey revealed customer preferences.","zh-TW":"調查揭示了客戶偏好。"}]', '{"noun":"revelation","adjective":"revealing"}', NULL, 2, 5698, NULL),
(5699, 'revenue', '/ˈrevənjuː/', 'noun', '{"zh-TW":["收入；營收","營收"],"en":["income, especially of a company or organization","income from business activities","income earned by a company"]}', '{"prefix":{"text":"re-","meaning":"back (回)"},"root":{"text":"venue","meaning":"come (來)"},"logic":"回來的錢，即「收入」。"}', 'annual revenue / revenue growth / generate revenue; revenue stream / revenue growth / total revenue', '[{"en":"The company''s annual revenue exceeded $1 billion.","zh-TW":"公司年營收超過10億美元。"},{"en":"Online sales are a major source of revenue.","zh-TW":"線上銷售是主要收入來源。"},{"en":"Annual revenue reached $50 million.","zh-TW":"年營收達到五千萬美元。"},{"en":"The new product line generates significant revenue.","zh-TW":"新產品線產生了可觀收入。"},{"en":"Total revenue exceeded expectations.","zh-TW":"總營收超出預期。"},{"en":"We need to diversify revenue streams.","zh-TW":"我們需要多元化收入來源。"}]', NULL, NULL, 3, 5699, 208);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5700, 'revenue forecast', '/ˈrɛvɪnjuː ˈfɔːrkɑːst/', 'noun', '{"zh-TW":["收益預測"],"en":["a projection of expected future revenue"]}', NULL, 'prepare a revenue forecast / accurate revenue forecast', '[{"en":"The revenue forecast for next year showed 20% growth.","zh-TW":"明年的收益預測顯示增長20%。"},{"en":"Management revised the revenue forecast after the market downturn.","zh-TW":"管理層在市場下滑後修訂了收益預測。"}]', NULL, NULL, 5, 5700, NULL),
(5701, 'revenue growth', '/ˈrevɪnjuː ɡroʊθ/', 'noun', '{"zh-TW":["收入增長"],"en":["an increase in a company''s total income from sales over a period"]}', NULL, 'drive revenue growth / revenue growth target', '[{"en":"The company achieved 15% revenue growth through new market entry.","zh-TW":"公司通過進入新市場實現了15%的收入增長。"},{"en":"Revenue growth is the primary metric for evaluating business performance.","zh-TW":"收入增長是評估業務績效的主要指標。"}]', NULL, NULL, 5, 5701, NULL),
(5702, 'revenue model', '/ˈrevɪnjuː ˈmɒdəl/', 'noun', '{"zh-TW":["收益模式"],"en":["the strategy a business uses to generate income"]}', NULL, 'subscription revenue model / freemium revenue model / advertising revenue model', '[{"en":"The startup switched from a freemium to a subscription revenue model.","zh-TW":"初創公司從免費增值轉換為訂閱收益模式。"},{"en":"A scalable revenue model is critical for investor confidence.","zh-TW":"可擴展的收益模式對於投資者信心至關重要。"}]', NULL, NULL, 5, 5702, NULL),
(5703, 'revenue per employee', '/ˈrevɪnjuː pɜːr ɪmˈplɔɪiː/', 'noun', '{"zh-TW":["人均收入"],"en":["a measure of how much revenue each employee generates on average"]}', NULL, 'calculate revenue per employee / improve revenue per employee', '[{"en":"Revenue per employee increased after the automation initiative.","zh-TW":"自動化計劃後人均收入增加了。"},{"en":"High revenue per employee indicates efficient use of human capital.","zh-TW":"高人均收入表明人力資本使用效率高。"}]', NULL, NULL, 5, 5703, NULL),
(5704, 'revenue recognition', '/ˈrevɪnjuː ˌrekəɡˈnɪʃən/', 'noun', '{"zh-TW":["收入確認"],"en":["the accounting principle governing when revenue is recognized in financial statements"]}', NULL, 'revenue recognition policy / apply revenue recognition standards', '[{"en":"Revenue recognition rules were updated under the new accounting standard.","zh-TW":"收入確認規則在新會計準則下進行了更新。"},{"en":"Improper revenue recognition led to the financial restatement.","zh-TW":"不當的收入確認導致了財務報表的重新申報。"}]', NULL, NULL, 5, 5704, NULL),
(5705, 'revenue stream', '/ˈrɛvɪnjuː striːm/', 'noun', '{"zh-TW":["收益來源"],"en":["a source of income for a business"]}', NULL, 'develop new revenue streams / diversify revenue streams', '[{"en":"The company developed multiple revenue streams to reduce risk.","zh-TW":"公司開發了多個收益來源以降低風險。"},{"en":"Subscription services became a significant revenue stream.","zh-TW":"訂閱服務成為了重要的收益來源。"}]', NULL, NULL, 5, 5705, NULL),
(5706, 'reverse', '/rɪˈvɜːrs/', 'verb', '{"zh-TW":["逆轉；撤銷"],"en":["to change to the opposite"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"verse","meaning":"turn (轉)"}}', 'reverse a decision / reverse the trend / in reverse', '[{"en":"The board reversed its earlier decision.","zh-TW":"董事會撤銷了先前的決定。"},{"en":"We need to reverse this downward trend.","zh-TW":"我們需要逆轉下降趨勢。"}]', '{"noun":"reversal","adjective":"reversible"}', NULL, 3, 5706, NULL),
(5707, 'reverse logistics', '/''rɪˈvɜːrs lɒˈdʒɪstɪks/', 'noun', '{"zh-TW":["逆向物流；退貨物流"],"en":["the process of moving goods from their final destination back to the manufacturer or seller for return or recycling"]}', NULL, 'manage reverse logistics / reverse logistics process / efficient reverse logistics', '[{"en":"Good reverse logistics management improves customer satisfaction for returned products.","zh-TW":"良好的逆向物流管理提高了退貨產品的客戶滿意度。"},{"en":"The company established a reverse logistics center to handle product recalls efficiently.","zh-TW":"公司建立了一個逆向物流中心，以有效地處理產品召回。"}]', NULL, NULL, 5, 5707, NULL),
(5708, 'reverse merger', '/rɪˈvɜːrs ˈmɜːrdʒər/', 'noun', '{"zh-TW":["反向合併"],"en":["a transaction in which a private company acquires a public company"]}', NULL, 'complete a reverse merger / pursue a reverse merger / reverse merger deal', '[{"en":"The startup went public through a reverse merger with a shell company.","zh-TW":"初創公司通過與殼公司的反向合併上市。"},{"en":"A reverse merger can be faster and cheaper than a traditional IPO.","zh-TW":"反向合併可以比傳統IPO更快更便宜。"}]', NULL, NULL, 5, 5708, NULL),
(5709, 'review', '/rɪˈvjuː/', 'noun', '{"zh-TW":["審查；評論"],"en":["an examination; an assessment"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"view","meaning":"see (看)"}}', 'performance review / under review / review process', '[{"en":"The application is currently under review.","zh-TW":"申請目前正在審查中。"},{"en":"Annual performance reviews start next week.","zh-TW":"年度績效考核下週開始。"}]', '{"verb":"review","noun":"reviewer"}', NULL, 2, 5709, 60),
(5710, 'revise', '/rɪˈvaɪz/', 'verb', '{"zh-TW":["修改；修訂","修訂"],"en":["to change or correct"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"vise","meaning":"see (看)"}}', 'revise the budget / revise upward / revised edition; revise the plan / revised estimate / subject to revision', '[{"en":"We need to revise the budget estimates.","zh-TW":"我們需要修改預算估計。"},{"en":"The forecast has been revised upward.","zh-TW":"預測已被上調修正。"},{"en":"The policy was revised last quarter.","zh-TW":"政策在上季度進行了修訂。"},{"en":"All figures are subject to revision.","zh-TW":"所有數字可能會修訂。"}]', '{"noun":"revision"}', NULL, 2, 5710, 209),
(5711, 'revolve', '/rɪˈvɒlv/', 'verb', '{"zh-TW":["圍繞；旋轉"],"en":["to move in a circle; to center on"]}', '{"prefix":{"text":"re-","meaning":"again"},"root":{"text":"volve","meaning":"roll (滾動)"}}', 'revolve around / revolving door / revolving credit', '[{"en":"The discussion revolved around cost reduction.","zh-TW":"討論圍繞著降低成本進行。"},{"en":"Our strategy revolves around innovation.","zh-TW":"我們的策略以創新為中心。"}]', '{"adjective":"revolving","noun":"revolution"}', NULL, 3, 5711, NULL),
(5712, 'revolving credit', '/rɪˈvɒlvɪŋ ˈkredɪt/', 'noun', '{"zh-TW":["循環信貸"],"en":["a credit facility that can be repeatedly used and repaid up to a limit"]}', NULL, 'draw on revolving credit / revolving credit facility', '[{"en":"The company used revolving credit to manage seasonal inventory needs.","zh-TW":"公司使用循環信貸來管理季節性庫存需求。"},{"en":"Revolving credit provides flexibility for short-term liquidity management.","zh-TW":"循環信貸為短期流動性管理提供了靈活性。"}]', NULL, NULL, 5, 5712, NULL),
(5713, 'reward', '/rɪˈwɔːrd/', 'noun', '{"zh-TW":["獎勵；報酬","獎勵"],"en":["something given in recognition","to give something good in return for effort"]}', '{"prefix":{"text":"re-","meaning":"back"},"root":{"text":"ward","meaning":"watch (看)"}}', 'reward for / rewards program / risk and reward; reward employees / reward loyalty / financially rewarding', '[{"en":"Hard work will bring its own reward.","zh-TW":"努力工作自有回報。"},{"en":"The company has a generous rewards program.","zh-TW":"公司有優厚的獎勵計劃。"},{"en":"We reward employees for excellent performance.","zh-TW":"我們獎勵表現優秀的員工。"},{"en":"The career is both challenging and rewarding.","zh-TW":"這份職業既有挑戰性又有回報。"}]', '{"verb":"reward","adjective":"rewarding","noun":"reward"}', NULL, 2, 5713, 210),
(5714, 'reward points', '/''rɪˈwɔːrd pɔɪnts/', 'noun', '{"zh-TW":["獎勵積分；回饋點數"],"en":["points accumulated through purchases or activities that can be redeemed for goods or services"]}', NULL, 'earn reward points / redeem reward points / accumulate reward points', '[{"en":"She earned reward points every time she used her travel credit card.","zh-TW":"她每次使用旅遊信用卡都能獲得獎勵積分。"},{"en":"Reward points can be redeemed for flights, hotel stays, or gift cards.","zh-TW":"獎勵積分可以兌換機票、飯店住宿或禮品卡。"}]', NULL, NULL, 5, 5714, NULL),
(5715, 'rhetoric', '/ˈretərɪk/', 'noun', '{"zh-TW":["修辭；花言巧語"],"en":["the art of effective or persuasive speaking or writing"]}', NULL, 'political rhetoric / empty rhetoric / rhetorical skill', '[{"en":"The politician''s rhetoric was powerful but lacking in substance.","zh-TW":"這位政治家的修辭很有力量，但缺乏實質內容。"},{"en":"Good rhetoric helps persuade audiences and win debates.","zh-TW":"良好的修辭有助於說服觀眾並贏得辯論。"}]', '{"adjective":"rhetorical","adverb":"rhetorically"}', NULL, 3, 5715, NULL),
(5716, 'rhetoric device', '/''retərɪk dɪˌvaɪs/', 'noun', '{"zh-TW":["修辭手法；修辭裝置"],"en":["a technique used in language to achieve a particular effect in writing or speech"]}', NULL, 'use a rhetoric device / effective rhetoric device / rhetorical device', '[{"en":"Metaphor is a common rhetoric device used to make abstract ideas more concrete.","zh-TW":"比喻是使抽象概念更具體的常用修辭手法。"},{"en":"Skilled speakers use rhetoric devices to make their presentations more memorable.","zh-TW":"熟練的演講者使用修辭手法使他們的演示更令人印象深刻。"}]', NULL, NULL, 5, 5716, NULL),
(5717, 'rheumatologist', '/ˌruːmətˈɒlədʒɪst/', 'noun', '{"zh-TW":["風濕科醫師"],"en":["a specialist in the diagnosis and treatment of autoimmune and rheumatic diseases"]}', NULL, 'consult a rheumatologist / qualified rheumatologist / rheumatologist appointment', '[{"en":"The rheumatologist prescribed biologics for the patient''s rheumatoid arthritis.","zh-TW":"風濕科醫師為患者的類風濕性關節炎開了生物製劑。"},{"en":"Autoimmune diseases like lupus are typically managed by a rheumatologist.","zh-TW":"狼瘡等自體免疫疾病通常由風濕科醫師管理。"}]', NULL, NULL, 5, 5717, NULL),
(5718, 'rich', '/rɪtʃ/', 'adjective', '{"zh-TW":["富有的；豐富的"],"en":["having a lot of money","containing a lot of something"]}', NULL, 'rich in / get rich', '[{"en":"The region is rich in natural resources.","zh-TW":"這個地區自然資源豐富。"},{"en":"The data provides rich insights.","zh-TW":"數據提供了豐富的洞見。"}]', '{"adjective":"rich","noun":"riches","adverb":"richly","verb":"enrich"}', NULL, 1, 5718, NULL),
(5719, 'ride', '/raɪd/', 'verb', '{"zh-TW":["騎；乘坐"],"en":["to sit on and control","to travel in a vehicle"]}', NULL, 'ride sharing / free ride', '[{"en":"Ride-sharing apps reduced transport costs.","zh-TW":"共乘應用程式降低了交通成本。"},{"en":"There is no free ride in business.","zh-TW":"商場上沒有不勞而獲。"}]', '{"verb":"ride","noun":"ride","noun2":"rider"}', NULL, 1, 5719, NULL),
(5720, 'right', 'raɪt', 'adjective', '{"zh-TW":["正確的；合適的","右邊的"],"en":["correct or appropriate","in the correct position"]}', NULL, 'right approach/right person', '[{"en":"Make sure you choose the right candidate.","zh-TW":"確保您選擇了正確的候選人。"}]', '{"noun":"right","adverb":"rightly"}', NULL, 2, 5720, NULL),
(5721, 'right of first refusal', '/raɪt əv fɜːrst rɪˈfjuːzəl/', 'noun', '{"zh-TW":["優先購買權"],"en":["the right to have the first opportunity to buy or accept an offer"]}', NULL, 'hold a right of first refusal / waive the right of first refusal', '[{"en":"The company holds a right of first refusal on any new share issuance.","zh-TW":"公司持有任何新股發行的優先購買權。"},{"en":"The partnership agreement includes a right of first refusal for buyouts.","zh-TW":"合夥協議包含收購的優先購買權條款。"}]', NULL, NULL, 5, 5721, NULL),
(5722, 'right to work', '/raɪt tə wɜːrk/', 'noun', '{"zh-TW":["工作權；勞動權"],"en":["the legal right of a person to be employed without discrimination"]}', NULL, 'protect the right to work / right to work legislation', '[{"en":"The company respects the right to work for all employees.","zh-TW":"公司尊重所有員工的工作權。"},{"en":"Right to work legislation affects union membership requirements.","zh-TW":"勞動權立法影響了工會成員資格要求。"}]', NULL, NULL, 5, 5722, NULL),
(5723, 'rights issue', '/raɪts ˈɪʃuː/', 'noun', '{"zh-TW":["供股；配股"],"en":["an offer to existing shareholders to buy new shares at a discounted price"]}', NULL, 'announce a rights issue / subscribe to a rights issue', '[{"en":"The company launched a rights issue to raise $50 million.","zh-TW":"公司啟動了供股以籌集5000萬元。"},{"en":"Shareholders who do not participate in a rights issue face dilution.","zh-TW":"未參與供股的股東面臨稀釋。"}]', NULL, NULL, 4, 5723, NULL),
(5724, 'rigid', '/ˈrɪdʒɪd/', 'adjective', '{"zh-TW":["嚴格的；僵硬的"],"en":["strict; not flexible"]}', '{"root":{"text":"rig","meaning":"stiff (僵硬)"}}', 'rigid rules / rigid structure / rigid schedule', '[{"en":"The company has very rigid policies.","zh-TW":"公司有非常嚴格的政策。"},{"en":"A rigid schedule leaves no room for creativity.","zh-TW":"僵化的日程不留創造空間。"}]', '{"noun":"rigidity","adverb":"rigidly"}', NULL, 2, 5724, NULL),
(5725, 'rigidity', '/rɪˈdʒɪdɪti/', 'noun', '{"zh-TW":["僵硬；死板；缺乏彈性"],"en":["the quality of being stiff or unyielding; inflexibility"]}', NULL, 'organizational rigidity / ideological rigidity / structural rigidity', '[{"en":"Excessive rigidity in rules can stifle creativity and innovation.","zh-TW":"規則中過度的死板會扼殺創造力和創新。"},{"en":"The rigidity of the framework made it difficult to adapt.","zh-TW":"框架的僵硬性使其難以適應變化。"}]', '{"adjective":"rigid","adverb":"rigidly"}', NULL, 3, 5725, NULL),
(5726, 'rigorous', '/ˈrɪɡərəs/', 'adjective', '{"zh-TW":["嚴格的；嚴謹的"],"en":["extremely thorough and careful"]}', NULL, 'rigorous testing / rigorous analysis / rigorous standards', '[{"en":"A rigorous peer review process ensures research quality.","zh-TW":"嚴格的同行評審過程確保研究品質。"},{"en":"The methodology must be rigorous to produce reliable results.","zh-TW":"方法論必須嚴謹才能產生可靠的結果。"}]', '{"noun":"rigor","adverb":"rigorously"}', NULL, 3, 5726, NULL),
(5727, 'ring', '/rɪŋ/', 'verb', '{"zh-TW":["響鈴；打電話"],"en":["to make a sound like a bell","to telephone"]}', NULL, 'ring a bell / give someone a ring', '[{"en":"Does the name ring a bell?","zh-TW":"這個名字你聽起來熟悉嗎？"},{"en":"Give me a ring tomorrow morning.","zh-TW":"明天早上打電話給我。"}]', '{"verb":"ring","noun":"ring"}', NULL, 1, 5727, NULL),
(5728, 'rise', '/raɪz/', 'verb', '{"zh-TW":["上升；增加"],"en":["to move upward","to increase"]}', NULL, 'give rise to / on the rise', '[{"en":"Remote work is on the rise.","zh-TW":"遠端工作正在增加。"},{"en":"This gave rise to new regulations.","zh-TW":"這引發了新的法規。"}]', '{"verb":"rise","noun":"rise"}', NULL, 1, 5728, NULL),
(5729, 'risk', '/rɪsk/', 'noun', '{"zh-TW":["風險","冒...的風險"],"en":["the possibility of danger or loss","to expose to danger"]}', NULL, 'take a risk / risk management / at risk / risk assessment; risk losing / risk assessment / risk management / at risk', '[{"en":"Every investment involves some degree of risk.","zh-TW":"每項投資都涉及一定程度的風險。"},{"en":"We need a comprehensive risk assessment.","zh-TW":"我們需要全面的風險評估。"},{"en":"We risk losing market share if we don''t innovate.","zh-TW":"如不創新我們就有失去市佔率的風險。"},{"en":"Effective risk management is crucial.","zh-TW":"有效的風險管理至關重要。"}]', '{"verb":"risk","adjective":"risky","noun":"risk"}', NULL, 1, 5729, NULL),
(5730, 'risk appetite', '/rɪsk ˈæpɪtaɪt/', 'noun', '{"zh-TW":["風險承受度；風險偏好"],"en":["the level of risk an organization is willing to accept"]}', NULL, 'define risk appetite / low risk appetite / risk appetite framework', '[{"en":"The board''s risk appetite guides all major investment decisions.","zh-TW":"董事會的風險承受度指導所有重大投資決策。"},{"en":"A higher risk appetite allows for more aggressive growth strategies.","zh-TW":"較高的風險偏好允許採取更激進的增長策略。"}]', NULL, NULL, 5, 5730, NULL),
(5731, 'risk assessment', '/rɪsk əˈsɛsmənt/', 'noun', '{"zh-TW":["風險評估"],"en":["an evaluation of potential hazards and their likelihood"]}', NULL, 'conduct a risk assessment / risk assessment report', '[{"en":"A risk assessment must be completed before the project begins.","zh-TW":"項目開始前必須完成風險評估。"},{"en":"Regular risk assessments help prevent workplace accidents.","zh-TW":"定期風險評估有助於預防工作場所事故。"}]', NULL, NULL, 5, 5731, NULL),
(5732, 'risk exposure', '/rɪsk ɪkˈspoʊʒər/', 'noun', '{"zh-TW":["風險敞口"],"en":["the extent to which a business or portfolio is affected by a particular risk"]}', NULL, 'manage risk exposure / reduce risk exposure', '[{"en":"The bank reduced its risk exposure by diversifying its loan portfolio.","zh-TW":"銀行通過多元化貸款組合降低了風險敞口。"},{"en":"Currency risk exposure must be hedged in international contracts.","zh-TW":"國際合約中的貨幣風險敞口必須進行對沖。"}]', NULL, NULL, 5, 5732, NULL),
(5733, 'risk management', '/rɪsk ˈmænɪdʒmənt/', 'noun', '{"zh-TW":["風險管理"],"en":["identifying and mitigating potential threats to a business"]}', NULL, 'risk management framework / enterprise risk management', '[{"en":"Risk management helped the firm avoid costly mistakes.","zh-TW":"風險管理幫助公司避免了代價高昂的錯誤。"},{"en":"A solid risk management process is required by regulators.","zh-TW":"監管機構要求有健全的風險管理流程。"}]', '{"verb":"manage risk","adjective":"risk-managed"}', NULL, 5, 5733, NULL),
(5734, 'risk management framework', '/rɪsk ˈmænɪdʒmənt ˈfreɪmwɜːrk/', 'noun', '{"zh-TW":["風險管理框架"],"en":["a structured system for identifying, assessing, and controlling risks"]}', NULL, 'implement a risk management framework / update the risk management framework', '[{"en":"The company implemented an enterprise risk management framework last year.","zh-TW":"公司去年實施了企業風險管理框架。"},{"en":"A robust risk management framework is required by financial regulators.","zh-TW":"金融監管機構要求具有健全的風險管理框架。"}]', NULL, NULL, 5, 5734, NULL),
(5735, 'risk mitigation', '/rɪsk ˌmɪtɪˈɡeɪʃən/', 'noun', '{"zh-TW":["風險緩解；風險降低"],"en":["actions taken to reduce the probability or impact of a risk"]}', NULL, 'implement risk mitigation measures / risk mitigation strategy', '[{"en":"Risk mitigation plans were developed for all major project risks.","zh-TW":"為所有主要項目風險制定了風險緩解計劃。"},{"en":"Insurance is one form of risk mitigation for property damage.","zh-TW":"保險是財產損失的一種風險緩解形式。"}]', NULL, NULL, 5, 5735, NULL),
(5736, 'risk premium', '/rɪsk ˈpriːmiəm/', 'noun', '{"zh-TW":["風險溢酬"],"en":["the additional return investors require for taking on greater risk"]}', NULL, 'calculate risk premium / equity risk premium', '[{"en":"Investors demand a higher risk premium for investing in emerging markets.","zh-TW":"投資者要求在新興市場投資有更高的風險溢酬。"},{"en":"The risk premium compensates for uncertainty in projected cash flows.","zh-TW":"風險溢酬補償了預期現金流的不確定性。"}]', NULL, NULL, 4, 5736, NULL),
(5737, 'risk register', '/rɪsk ˈredʒɪstər/', 'noun', '{"zh-TW":["風險登記冊"],"en":["a document listing identified project risks and mitigation strategies"]}', NULL, 'maintain a risk register / update the risk register / review the risk register', '[{"en":"The risk register was updated after the supplier delayed delivery.","zh-TW":"供應商延遲交貨後，風險登記冊進行了更新。"},{"en":"All project risks are documented in the risk register.","zh-TW":"所有項目風險都記錄在風險登記冊中。"}]', NULL, NULL, 5, 5737, NULL),
(5738, 'risk-adjusted return', '/rɪsk əˈdʒʌstɪd rɪˈtɜːrn/', 'noun', '{"zh-TW":["風險調整後回報"],"en":["investment return adjusted to account for the risk taken"]}', NULL, 'calculate risk-adjusted return / compare risk-adjusted returns', '[{"en":"Investors compare risk-adjusted returns to evaluate fund performance.","zh-TW":"投資者比較風險調整後回報以評估基金績效。"},{"en":"A high risk-adjusted return indicates efficient use of risk capital.","zh-TW":"高風險調整後回報表明風險資本使用效率高。"}]', NULL, NULL, 5, 5738, NULL),
(5739, 'river', '/ˈrɪvər/', 'noun', '{"zh-TW":["河流"],"en":["a large natural stream of water"]}', NULL, 'down the river / river bank', '[{"en":"The factory is located along the river.","zh-TW":"工廠坐落在河邊。"},{"en":"Don''t sell your team down the river.","zh-TW":"不要出賣你的團隊。"}]', '{"noun":"river","noun2":"riverside"}', NULL, 2, 5739, NULL),
(5740, 'road', '/roʊd/', 'noun', '{"zh-TW":["道路"],"en":["a path for vehicles and people"]}', NULL, 'on the road / road map', '[{"en":"Our sales team is always on the road.","zh-TW":"我們的業務團隊總是在外跑。"},{"en":"Here is our product road map.","zh-TW":"這是我們的產品路線圖。"}]', '{"noun":"road","noun2":"roadblock"}', NULL, 1, 5740, NULL),
(5741, 'road trip', '/''rəʊd trɪp/', 'noun', '{"zh-TW":["公路旅行；駕車旅遊"],"en":["a long journey made by car, often with stops along the way"]}', NULL, 'plan a road trip / go on a road trip / road trip route', '[{"en":"They planned a two-week road trip along the Pacific Coast Highway.","zh-TW":"他們規劃了一次沿太平洋海岸公路的兩週公路旅行。"},{"en":"A road trip offers the freedom to stop wherever you want along the way.","zh-TW":"公路旅行提供了在途中隨意停車的自由。"}]', NULL, NULL, 3, 5741, NULL),
(5742, 'roadmap', '/ˈroʊdmæp/', 'noun', '{"zh-TW":["路線圖；發展規劃"],"en":["a strategic plan outlining goals and the steps to achieve them"]}', NULL, 'create a roadmap / product roadmap / technology roadmap', '[{"en":"The board approved a three-year roadmap for digital transformation.","zh-TW":"董事會批准了數位轉型的三年路線圖。"},{"en":"The product roadmap guides the development team''s priorities.","zh-TW":"產品路線圖指導了開發團隊的優先事項。"}]', NULL, NULL, 3, 5742, NULL),
(5743, 'roam', '/''rəʊm/', 'verb', '{"zh-TW":["漫游；四處漫步"],"en":["to move about or travel aimlessly or unsystematically over a wide area"]}', NULL, 'roam freely / roam the streets / roam the countryside', '[{"en":"Wild horses roam freely across the plains of the national park.","zh-TW":"野馬在國家公園的平原上自由漫游。"},{"en":"She loved to roam through the old neighborhoods, discovering hidden cafés.","zh-TW":"她喜歡在老街區漫步，發現隱藏的咖啡館。"}]', NULL, NULL, 1, 5743, NULL),
(5744, 'roast', '/''rəʊst/', 'verb', '{"zh-TW":["烘烤；烤"],"en":["to cook food in an oven or over a fire with dry heat"]}', NULL, 'roast in the oven / slow roast / roast vegetables', '[{"en":"She roasted the chicken at 200 degrees Celsius for one and a half hours.","zh-TW":"她在200攝氏度下烤了一個半小時的雞肉。"},{"en":"Roasting vegetables caramelizes their natural sugars and enhances their flavor.","zh-TW":"烤蔬菜會使其天然糖分焦糖化，增強風味。"}]', '{"noun":"roast","adjective":"roasted"}', NULL, 2, 5744, NULL),
(5745, 'robust', '/rəˈbʌst/', 'adjective', '{"zh-TW":["穩健的；強健的"],"en":["strong and unlikely to fail; thorough and effective"]}', NULL, 'robust system / robust evidence / robust approach', '[{"en":"The company needs a robust risk management framework.","zh-TW":"公司需要一個穩健的風險管理框架。"},{"en":"The study provides robust evidence supporting the intervention.","zh-TW":"研究提供了支持干預的強健證據。"}]', '{"noun":"robustness","adverb":"robustly"}', NULL, 2, 5745, NULL),
(5746, 'role', '/roʊl/', 'noun', '{"zh-TW":["角色；職責"],"en":["a function; a part played"]}', NULL, 'play a role / key role / role model / in the role of', '[{"en":"Technology plays a key role in our strategy.","zh-TW":"技術在我們策略中發揮關鍵作用。"},{"en":"She excels in her role as project lead.","zh-TW":"她在項目負責人的角色中表現出色。"}]', NULL, NULL, 1, 5746, 211),
(5747, 'rolling average', '/ˈroʊlɪŋ ˈævərɪdʒ/', 'noun', '{"zh-TW":["滾動平均"],"en":["an average recalculated over successive time periods as new data is added"]}', NULL, 'calculate rolling average / 3-month rolling average', '[{"en":"A 12-month rolling average smooths out short-term fluctuations in revenue.","zh-TW":"12個月滾動平均消除了收入的短期波動。"},{"en":"Rolling averages are used in trend analysis and forecasting.","zh-TW":"滾動平均用於趨勢分析和預測。"}]', NULL, NULL, 5, 5747, NULL),
(5748, 'rolling basis', '/ˈroʊlɪŋ ˈbeɪsɪs/', 'noun', '{"zh-TW":["滾動基準；持續更新的基準"],"en":["an ongoing arrangement reviewed and renewed continuously"]}', NULL, 'on a rolling basis / rolling basis contract', '[{"en":"Staff are admitted to the program on a rolling basis throughout the year.","zh-TW":"員工在全年滾動基準上入選計劃。"},{"en":"The contract renews automatically on a rolling basis annually.","zh-TW":"合約每年自動以滾動基準續期。"}]', NULL, NULL, 5, 5748, NULL),
(5749, 'rolling budget', '/ˈroʊlɪŋ ˈbʌdʒɪt/', 'noun', '{"zh-TW":["滾動預算"],"en":["a budget that is continuously updated by adding a new period as the current one ends"]}', NULL, 'use a rolling budget / rolling budget cycle', '[{"en":"A rolling budget ensures projections remain current throughout the year.","zh-TW":"滾動預算確保預測在全年保持最新狀態。"},{"en":"The company switched to a rolling budget to improve financial agility.","zh-TW":"公司改用滾動預算以提高財務靈活性。"}]', NULL, NULL, 5, 5749, NULL);